        Ok(stdcode::deserialize(
            &db_read(ctx, &format!("conn_token_{epoch}"))
                .await?
                .context("absent right now")?,
        )?)
    } else {
        Ok(stdcode::deserialize(
            &db_read_or_wait(ctx, &format!("conn_token_{epoch}")).await?,
        )?)
    }
